from typing import TYPE_CHECKING, Any

import linopy
import pandas as pd
import xarray as xr
from deprecation import deprecated
from numpy import hstack, ravel, roll, zeros

from pypsa._options import options
from pypsa.components.array import (
    _flat_snapshot_coords,
    _flat_snapshot_index,
    _flatten_snapshots,
    _unflatten_snapshots,
)
from pypsa.constants import RE_PORTS

if TYPE_CHECKING:
    from collections.abc import Iterator

    from linopy import Model, Variable

    from pypsa import Network

MODEL_SNAPSHOT_INDEX_VALUES = ("auto", "multiindex", "flat")


def _linopy_v1_semantics() -> bool:
    """Whether linopy's v1 semantics are active."""
    try:
        return linopy.options["semantics"] == "v1"
    except KeyError:
        return False


def _resolve_model_snapshot_index() -> str:
    """Resolve `options.optimization.model_snapshot_index` to "multiindex" or "flat"."""
    value = options.optimization.model_snapshot_index
    if value not in MODEL_SNAPSHOT_INDEX_VALUES:
        msg = (
            f"Invalid value {value!r} for option "
            "'optimization.model_snapshot_index'. Must be one of "
            f"{', '.join(map(repr, MODEL_SNAPSHOT_INDEX_VALUES))}."
        )
        raise ValueError(msg)
    if value == "auto":
        return "flat" if _linopy_v1_semantics() else "multiindex"
    return value


def _model_snapshot_parameter(sns: pd.Index, flat: bool) -> pd.Index | xr.DataArray:
    """Snapshots as stored in the model parameters."""
    if not flat:
        return sns
    return xr.DataArray(
        _flat_snapshot_index(sns), coords=_flat_snapshot_coords(sns), dims="snapshot"
    )


def _model_is_flat(m: Model) -> bool:
    """Whether the model labels multi-period snapshots by a flat index."""
    if "snapshots" not in m.parameters:
        return False
    snapshots = m.parameters["snapshots"]
    return "period" in snapshots.coords and not isinstance(
        snapshots.indexes.get("snapshot"), pd.MultiIndex
    )


def _model_snapshots(n: Network) -> pd.Index:
    """Snapshots of the model in its own representation."""
    return n.model.parameters.snapshots.to_index()


def _network_snapshots(n: Network, sns: pd.Index) -> pd.Index:
    """Convert model snapshots back to the network's snapshot index."""
    if isinstance(n.snapshots, pd.MultiIndex) and not isinstance(sns, pd.MultiIndex):
        sns = pd.MultiIndex.from_tuples(sns, names=n.snapshots.names)
        sns.name = "snapshot"
    return sns


@contextmanager
def _snapshot_representation(n: Network, flat: bool) -> Iterator[None]:
    """Let component data be read in the model's snapshot representation."""
    previous = n._flat_model_snapshots
    n._flat_model_snapshots = flat
    try:
        yield
    finally:
        n._flat_model_snapshots = previous


def _as_model_snapshots(n: Network, obj: Any) -> Any:
    """Convert snapshot-indexed data to the snapshot representation of the model.

    Supports snapshot indexes, pandas objects indexed by snapshots and xarray
    objects with a snapshot dimension. Other objects are returned unchanged.
    """
    if not _model_is_flat(n.model):
        return obj
    if isinstance(obj, pd.MultiIndex):
        return _flat_snapshot_index(obj)
    if isinstance(obj, pd.Series | pd.DataFrame):
        if isinstance(obj.index, pd.MultiIndex) and obj.index.names == list(
            n.snapshots.names
        ):
            return obj.set_axis(_flat_snapshot_index(obj.index), axis=0)
        return obj
    if isinstance(obj, xr.DataArray | xr.Dataset):
        return _flatten_snapshots(obj)
    return obj


def _period_start_mask(sns: pd.Index) -> xr.DataArray:
    """Mark the first snapshot of each investment period."""
    is_start = zeros(len(sns), dtype=bool)
    is_start[0] = True
    if isinstance(sns, pd.MultiIndex) and "period" in sns.names:
        periods = sns.get_level_values("period").to_numpy()
        is_start[1:] = periods[1:] != periods[:-1]
    return xr.DataArray(is_start, coords=[sns])


def _roll_within_periods(v: Variable) -> Variable:
    """Cyclically roll ``v`` by one snapshot within each investment period."""
    coords = v.coords
    sns = _unflatten_snapshots(xr.Dataset(coords=coords)).indexes["snapshot"]
    positions = pd.Series(range(len(sns)), index=sns)
    roll_index = positions.groupby(level="period").transform(lambda s: roll(s, 1))
    if isinstance(v.indexes["snapshot"], pd.MultiIndex):
        coords = xr.Coordinates.from_pandas_multiindex(sns, "snapshot")
    else:
        coords = _flat_snapshot_coords(sns)
    return v.isel(snapshot=roll_index.to_numpy()).assign_coords(coords)

