"""Compare harness outputs. usage: python compare.py base.pkl other.pkl [-v]"""

import pickle
import sys

import numpy as np
import pandas as pd
import xarray as xr

base = pickle.load(open(sys.argv[1], "rb"))
other = pickle.load(open(sys.argv[2], "rb"))
verbose = "-v" in sys.argv


def to_pd(x):
    if isinstance(x, xr.DataArray):
        # flatten snapshot representation to compare values only
        if "snapshot" in x.dims and not isinstance(
            x.indexes.get("snapshot"), pd.MultiIndex
        ):
            x = x.drop_vars(
                [c for c in x.coords if c != "snapshot" and x[c].dims == ("snapshot",)]
            )
        try:
            return x.to_series() if x.ndim else float(x)
        except Exception:
            return x.values
    return x


def close(a, b):
    if isinstance(a, str) or isinstance(b, str):
        return (a == b), f"{str(a)[:150]} | {str(b)[:150]}"
    a, b = to_pd(a), to_pd(b)
    if isinstance(a, float | int | np.floating) and isinstance(
        b, float | int | np.floating
    ):
        return bool(np.isclose(a, b, rtol=1e-5, atol=1e-3)), f"{a} vs {b}"
    if isinstance(a, tuple):
        return a == b, f"{a} vs {b}"
    try:
        av = np.asarray(a.values if hasattr(a, "values") else a, dtype=float)
        bv = np.asarray(b.values if hasattr(b, "values") else b, dtype=float)
    except Exception as e:
        return False, f"cannot convert {e}"
    if av.shape != bv.shape:
        return False, f"shape {av.shape} vs {bv.shape}"
    ok = np.allclose(np.nan_to_num(av), np.nan_to_num(bv), rtol=1e-4, atol=1e-2)
    idx_ok = True
    if isinstance(a, pd.Series | pd.DataFrame) and isinstance(b, type(a)):
        idx_ok = a.index.equals(b.index)
        if not idx_ok:
            ok = False
    diff = np.nanmax(np.abs(av - bv)) if av.size else 0
    return ok, f"maxdiff {diff} idx_ok {idx_ok}"


nfail = 0
for net, res in base.items():
    o = other.get(net, {})
    if "error" in res or "error" in o:
        print(f"[{net}] ERROR base={res.get('error', '')[-300:]} other={o.get('error', '')[-600:]}")
        nfail += 1
        continue
    for k, v in res.items():
        if k not in o:
            print(f"[{net}] missing {k}")
            nfail += 1
            continue
        ok, msg = close(v, o[k])
        if not ok:
            nfail += 1
            print(f"[{net}] DIFF {k}: {msg}")
        elif verbose:
            print(f"[{net}] ok {k}")
print("total diffs:", nfail)

