"""Build models under given semantics and dump a canonical LP representation.

usage: python lpcanon.py <semantics> <snapshot_index_option> <out.pkl> [networks]
"""

import pickle
import sys
import warnings
from collections import Counter

import linopy
import numpy as np
import pandas as pd

import pypsa

warnings.simplefilter("ignore")
import logging

logging.disable(logging.WARNING)

sem, opt, out = sys.argv[1:4]
only = sys.argv[4].split(",") if len(sys.argv) > 4 else None
linopy.options["semantics"] = sem
pypsa.options.optimization.model_snapshot_index = opt
pypsa.options.params.optimize.include_objective_constant = False

src = open("/tmp/harness.py").read()
exec(src[src.index("def multi_period():") : src.index("STATS = ")])


def flat_key(values):
    key = []
    for v in values:
        if isinstance(v, tuple):
            key.extend(v)
        else:
            key.append(v)
    return tuple(str(k) for k in key)


def canon(m):
    labelmap = {}
    bounds = Counter()
    for name, var in m.variables.items():
        labels = var.labels
        df = labels.to_dataframe("label").reset_index()
        coords = [c for c in df.columns if c not in ("label",) and c in labels.dims]
        lower = var.lower.broadcast_like(labels).values.ravel()
        upper = var.upper.broadcast_like(labels).values.ravel()
        lab = labels.values.ravel()
        idx = df[coords].to_numpy() if coords else np.empty((len(df), 0))
        for i, (l, row) in enumerate(zip(df["label"].to_numpy(), idx)):
            if l == -1:
                continue
            labelmap[l] = (name, flat_key(row))
        for l, lo, up, row in zip(lab, lower, upper, idx):
            if l != -1:
                bounds[(name, flat_key(row), round(float(lo), 6), round(float(up), 6))] += 1
    rows = Counter()
    for name, con in m.constraints.items():
        flat = con.flat
        if flat.empty:
            continue
        for label, g in flat.groupby("labels"):
            terms = Counter()
            for v, c in zip(g["vars"], g["coeffs"]):
                if v == -1:
                    continue
                terms[labelmap[v]] += c
            terms = tuple(sorted((k, round(c, 6)) for k, c in terms.items() if abs(c) > 1e-12))
            rows[(name, terms, g["sign"].iloc[0], round(float(g["rhs"].iloc[0]), 6))] += 1
    obj = Counter()
    of = m.objective.flat
    for v, c in zip(of["vars"], of["coeffs"]):
        if v != -1:
            obj[labelmap[v]] += c
    obj = {k: round(c, 6) for k, c in obj.items() if abs(c) > 1e-12}
    return {"rows": rows, "bounds": bounds, "obj": obj}


res = {}
for key, make in NETWORKS.items():
    if only and key not in only:
        continue
    try:
        n, kw = make()
        if key == "model_energy":
            n.set_snapshots(n.snapshots[:50])
        kw = {k: v for k, v in kw.items()}
        n.optimize.create_model(**kw)
        res[key] = canon(n.model)
    except Exception as e:
        import traceback

        res[key] = traceback.format_exc()
pickle.dump(res, open(out, "wb"))
print("saved")

