"""Pytest plugin recording canonical LPs of all models built/solved in tests."""

import os
import pickle
import sys
from collections import Counter, defaultdict

import linopy
import numpy as np
import pandas as pd

sys.path.insert(0, "/tmp")

RECORDS = {}
COUNTS = defaultdict(int)
MAX_ROWS = 30000


def flat_key(values):
    key = []
    for v in values:
        if isinstance(v, tuple):
            key.extend(v)
        else:
            key.append(v)
    return tuple(str(k) for k in key)


def canon(m):
    if m.constraints.ncons > MAX_ROWS:
        return "too large"
    labelmap = {}
    bounds = Counter()
    for name, var in m.variables.items():
        labels = var.labels
        df = labels.to_dataframe("label").reset_index()
        coords = []
        for d in labels.dims:
            index = labels.indexes.get(d)
            coords += list(index.names) if isinstance(index, pd.MultiIndex) else [d]
        lower = var.lower.broadcast_like(labels).values.ravel()
        upper = var.upper.broadcast_like(labels).values.ravel()
        lab = labels.values.ravel()
        idx = df[coords].to_numpy() if coords else np.empty((len(df), 0))
        for l, row in zip(df["label"].to_numpy(), idx):
            if l != -1:
                labelmap[l] = (name, flat_key(row))
        for l, lo, up, row in zip(lab, lower, upper, idx):
            if l != -1:
                bounds[(name, flat_key(row), round(float(lo), 5), round(float(up), 5))] += 1
    rows = Counter()
    for name, con in m.constraints.items():
        flat = con.flat
        if flat.empty:
            continue
        for _, g in flat.groupby("labels"):
            terms = Counter()
            for v, c in zip(g["vars"], g["coeffs"]):
                if v != -1:
                    terms[labelmap[v]] += c
            terms = tuple(
                sorted((k, round(c, 5)) for k, c in terms.items() if abs(c) > 1e-10)
            )
            rows[(name, terms, g["sign"].iloc[0], round(float(g["rhs"].iloc[0]), 5))] += 1
    obj = Counter()
    try:
        of = m.objective.flat
        for v, c in zip(of["vars"], of["coeffs"]):
            if v != -1:
                obj[labelmap.get(v, v)] += c
    except Exception as e:  # quadratic etc.
        obj["error"] = str(e)[:50]
    obj = {k: round(c, 5) for k, c in obj.items() if not isinstance(c, float) or abs(c) > 1e-10}
    return {"rows": rows, "bounds": bounds, "obj": obj}


def _record(tag, m):
    test = os.environ.get("PYTEST_CURRENT_TEST", "?").rsplit(" ", 1)[0]
    COUNTS[(test, tag)] += 1
    key = (test, tag, COUNTS[(test, tag)])
    try:
        RECORDS[key] = canon(m)
    except Exception as e:
        RECORDS[key] = f"canon error {type(e).__name__}: {e}"[:200]


def pytest_configure(config):
    from pypsa.optimization.optimize import OptimizationAccessor

    orig_create = OptimizationAccessor.create_model

    def create_model(self, *args, **kwargs):
        m = orig_create(self, *args, **kwargs)
        _record("create", m)
        return m

    OptimizationAccessor.create_model = create_model
    orig_solve = linopy.Model.solve

    def solve(self, *args, **kwargs):
        _record("solve", self)
        return orig_solve(self, *args, **kwargs)

    linopy.Model.solve = solve


def pytest_unconfigure(config):
    worker = os.environ.get("PYTEST_XDIST_WORKER", "main")
    out = os.environ.get("LPPLUGIN_OUT", "/tmp/lprec")
    os.makedirs(out, exist_ok=True)
    with open(f"{out}/{worker}.pkl", "wb") as f:
        pickle.dump(RECORDS, f)

